#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;

    void serialise(auto& stream) {
        // Write packet_id
        stream & packet_id;

        // Write username with length prefix (default string serialization)
        stream & username;

        // Write scores vector: count first, then elements
        uint32_t count = static_cast<uint32_t>(scores.size());
        stream & count;
        stream << scores;

        // Write metadata as null-terminated string
        stream & hexi::null_terminated(metadata);
    }
};

std::vector<uint8_t> serialize_packet(const NetworkPacket& packet) {
    // Create a dynamic buffer for writing
    hexi::dynamic_buffer<512> buffer;

    // Create a binary stream for serialization
    hexi::binary_stream stream(buffer);

    // Serialize the packet (cast to non-const to allow serialization)
    auto& packet_ref = const_cast<NetworkPacket&>(packet);
    stream.serialise(packet_ref);

    // Extract the serialized data into a vector
    std::vector<uint8_t> result(buffer.size());
    buffer.copy(result.data(), buffer.size());

    return result;
}
```

