   130→TEST(binary_stream, read_write_vector) {
   131→	hexi::dynamic_buffer<32> buffer;
   132→	hexi::binary_stream stream(buffer);
   133→
   134→	const auto time = std::chrono::system_clock::now().time_since_epoch();
   135→	const unsigned int seed = static_cast<unsigned int>(time.count());
   136→	std::srand(seed);
   137→
   138→	std::vector<int> in(std::rand() % 200);
   139→	std::ranges::iota(in, std::rand() % 100);
   140→	std::ranges::shuffle(in, std::default_random_engine(seed));
   141→
   142→	stream.put(in.begin(), in.end());
   143→
   144→	ASSERT_EQ(stream.size(), in.size() * sizeof(int));
   145→
   146→	// read the integers back one by one, making sure they
   147→	// match the expected value
   148→	for(auto it = in.begin(); it != in.end(); ++it) {
   149→		int output;
   150→		stream >> output;
   151→		ASSERT_EQ(output, *it);
   152→	}
   153→
   154→	stream.put(in.begin(), in.end());
   155→	std::vector<int> out(in.size());
   156→
   157→	// read the integers to an output buffer and compare both
   158→	stream.get(out.begin(), out.end());
   159→	ASSERT_EQ(in, out);
   160→	ASSERT_EQ(stream.state(), hexi::stream_state::ok)
   161→		<< "Unexpected stream state";
   162→}
