std::vector<uint8_t> read_buffer_data(const std::vector<uint8_t>& source_buffer, size_t bytes_to_read) {
    // Create a mutable copy of the source buffer since buffer_adaptor requires a non-const reference
    std::vector<uint8_t> buffer_copy = source_buffer;

    // Create a buffer_adaptor to manage reading from the buffer
    hexi::buffer_adaptor adaptor(buffer_copy);

    // Create destination buffer to hold the read data
    std::vector<uint8_t> result(bytes_to_read);

    // Read the specified number of bytes from the adaptor into the result buffer
    adaptor.read(result.data(), bytes_to_read);

    return result;
}

void write_buffer_data(std::vector<uint8_t>& dest_buffer, const std::vector<uint8_t>& source_data) {
    // Create a buffer_adaptor with the destination buffer initialized as empty
    // This ensures writes start at position 0
    hexi::buffer_adaptor adaptor(dest_buffer, hexi::init_empty);

    // Write the source data to the destination buffer via the adaptor
    adaptor.write(source_data.data(), source_data.size());
}
```

