   136→	/**
   137→	 * @brief Write data to the container.
   138→	 * 
   139→	 * @note The source buffer must not overlap with the underlying buffer
   140→	 * being used by the buffer_adaptor.
   141→	 * 
   142→	 * @param source Pointer to the data to be written.
   143→	 */
   144→	void write(const auto& source) {
