DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    // Create a buffer_adaptor from the span
    // Note: We need to create a mutable copy since buffer_adaptor requires non-const reference
    std::vector<uint8_t> buffer_vec(buffer.begin(), buffer.end());
    hexi::buffer_adaptor adaptor(buffer_vec);

    // Preview the first byte (data_type) without advancing the read pointer
    adaptor.copy(&result.data_type, sizeof(uint8_t));

    // Check if we have enough data (at least 5 bytes: 1 for type + 4 for count)
    if (adaptor.size() < sizeof(uint8_t) + sizeof(uint32_t)) {
        return result; // Return empty result if not enough data
    }

    // Create a binary_stream for reading
    hexi::binary_stream stream(adaptor);

    // Read the data_type (advances the pointer)
    stream >> result.data_type;

    // Read the item count (uint32_t)
    uint32_t item_count = 0;
    stream >> item_count;

    // Check if we have enough data for all items
    size_t item_size = (result.data_type == 0) ? sizeof(uint32_t) : sizeof(float);
    size_t required_size = sizeof(uint8_t) + sizeof(uint32_t) + (item_count * item_size);

    if (buffer.size() < required_size || !stream.good()) {
        return result; // Return partially filled result if not enough data
    }

    // Read items based on data type
    if (result.data_type == 0) {
        // Read integers
        result.int_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
