    33→int main() {
    34→    // note: you can use prefixed or prefixed_varint
    35→    // prefixed: uses a 32-bit unsigned integer to store container size
    36→    // prefixed_varint: compresses container size into a variable number of bytes (more compact but slower)
    37→    std::vector<char> buffer;
    38→    hexi::buffer_adaptor ba(buffer);
    39→    hexi::binary_stream stream(ba);
    40→
    41→    { // trivial types just work
    42→        std::vector input { 1, 2, 3, 4, 5 };
    43→        stream << hexi::prefixed(input);
    44→
    45→        std::vector<int> output;
    46→        stream >> hexi::prefixed(output);
    47→        std::cout << std::boolalpha << (input == output) << '\n';
    48→    }
    49→
    50→    { // more complicated types
    51→        std::vector<Widget> input;
    52→
    53→        // make some widgets
    54→        for(auto i = 0; i < 5; ++i) {
    55→            Widget w;
    56→            w.add_component({ 100, i });
    57→            input.emplace_back(std::move(w));
    58→        }
    59→
    60→        stream << hexi::prefixed(input);
    61→
    62→        // get them back out
    63→        std::vector<Widget> output;
    64→        stream >> hexi::prefixed(output);
    65→        std::cout << std::boolalpha << (input == output);
    66→    }
    67→}

