    // Get the read pointer to check available data
    auto read_ptr = adaptor.read_ptr();

    // Check available data (header size = 4 + 2 + 2 = 8 bytes)
    constexpr size_t header_size = sizeof(PacketHeader);
    if (adaptor.size() < header_size) {
        // Return zeroed header if not enough data
        return PacketHeader{0, 0, 0};
