#include <hexi/hexi.h>
#include <cstdint>
#include <span>

struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a buffer_adaptor from the span
    // We need to create a mutable vector from the span for buffer_adaptor
    std::vector<uint8_t> buf_vec(buffer.begin(), buffer.end());
    hexi::buffer_adaptor adaptor(buf_vec);

    // Create a binary_stream from the buffer_adaptor
    hexi::binary_stream stream(adaptor);

    // Get the read pointer to check available data
    auto read_ptr = adaptor.read_ptr();

    // Check available data (header size = 4 + 2 + 2 = 8 bytes)
    constexpr size_t header_size = sizeof(PacketHeader);
    if (adaptor.size() < header_size) {
        // Return zeroed header if not enough data
        return PacketHeader{0, 0, 0};
    }

    // Get a zero-copy view of the header using span
    auto header_span = stream.span<uint8_t>(header_size);

    // Parse the header from the span
    PacketHeader header;

    // Assuming little-endian byte order, read the fields
    std::memcpy(&header.magic, header_span.data(), sizeof(uint32_t));
    std::memcpy(&header.version, header_span.data() + sizeof(uint32_t), sizeof(uint16_t));
    std::memcpy(&header.flags, header_span.data() + sizeof(uint32_t) + sizeof(uint16_t), sizeof(uint16_t));

    return header;
}
```

