MessagePacket read_header_and_message(const std::span<const uint8_t> buffer) {
    // Create a buffer_adaptor from the span
    // Note: We need to cast away const since buffer_adaptor needs a mutable reference
    // but we won't modify the underlying data through reads
    auto mutable_buffer = const_cast<std::span<uint8_t>&>(
