    10→#include <hexi/shared.h>
    11→#include <hexi/allocators/default_allocator.h>
    12→#include <hexi/detail/intrusive_storage.h>
    13→#include <concepts>
    14→#include <functional>
    15→#include <memory>
    16→#include <utility>
    17→#ifdef HEXI_BUFFER_DEBUG
    18→#include <algorithm>
    19→#include <vector>
    20→#endif
    21→#include <cstddef>
    22→#include <cstdint>
    23→#include <cassert>
    24→
    25→namespace hexi {
    26→
    27→using namespace detail;
    28→
    29→template<typename buffer_type>
    30→class buffer_sequence;
    31→
    32→template<decltype(auto) block_sz>
    33→concept int_gt_zero = std::integral<decltype(block_sz)> && block_sz > 0;
    34→
    35→template<decltype(auto) block_sz,
    36→	byte_type storage_value_type = std::byte,
    37→	typename allocator = default_allocator<detail::intrusive_storage<block_sz, storage_value_type>>
    38→>
    39→requires int_gt_zero<block_sz>
    40→class dynamic_buffer final : public pmc::buffer {
    41→public:
    42→	using storage_type = intrusive_storage<block_sz, storage_value_type>;
    43→	using value_type   = storage_value_type;
    44→	using node_type    = intrusive_node;
    45→	using size_type    = std::size_t;
    46→	using offset_type  = std::size_t;
    47→	using contiguous   = is_non_contiguous;
    48→	using seeking      = supported;
    49→
    50→	static constexpr auto npos { static_cast<size_type>(-1) };
    51→
    52→	using unique_storage = std::unique_ptr<storage_type, std::function<void(storage_type*)>>;
    53→
    54→private:
    55→	intrusive_node root_;
    56→	size_type size_;
    57→	[[no_unique_address]] allocator allocator_;
    58→
    59→	void link_tail_node(intrusive_node* node) {
    60→		node->next = &root_;
    61→		node->prev = root_.prev;
    62→		root_.prev = root_.prev->next = node;
    63→	}
    64→
    65→	void unlink_node(intrusive_node* node) {
    66→		node->next->prev = node->prev;
    67→		node->prev->next = node->next;
    68→	}
    69→
    70→	inline storage_type* buffer_from_node(const intrusive_node* node) const {
    71→		return reinterpret_cast<storage_type*>(std::uintptr_t(node)
    72→			- offsetof(storage_type, node));
    73→	}
    74→
    75→	void move(dynamic_buffer& rhs) noexcept {
    76→		if(this == &rhs) { // self-assignment
    77→			return;
    78→		}
    79→
    80→		clear(); // clear our current blocks rather than swapping them
    81→
    82→		size_ = rhs.size_;
    83→		root_ = rhs.root_;
    84→		root_.next->prev = &root_;
    85→		root_.prev->next = &root_;
    86→		rhs.size_ = 0;
    87→		rhs.root_.next = &rhs.root_;
    88→		rhs.root_.prev = &rhs.root_;
    89→	}
    90→
    91→	void copy(const dynamic_buffer& rhs) {
    92→		if(this == &rhs) { // self-assignment
    93→			return;
    94→		}
    95→
    96→		const intrusive_node* head = rhs.root_.next;
    97→		root_.next = &root_;
    98→		root_.prev = &root_;
    99→		size_ = 0;
   100→
   101→		while(head != &rhs.root_) {
   102→			auto buffer = allocate();
   103→			*buffer = *buffer_from_node(head);
   104→			link_tail_node(&buffer->node);
   105→			size_ += buffer->write_offset;
   106→			head = head->next;
   107→		}
   108→	}
   109→	
   110→#ifdef HEXI_BUFFER_DEBUG
   111→	void offset_buffers(std::vector<storage_type*>& buffers, size_type offset) {
   112→		std::erase_if(buffers, [&](auto block) {
   113→			if(block->size() > offset) {
   114→				block->read_offset += offset;
   115→				block->write_offset -= offset;
   116→				return false;
   117→			} else {
   118→				return true;
   119→			}
   120→		});
   121→	}
   122→#endif
   123→
   124→	value_type& byte_at_index(const size_type index) const {
   125→		assert(index < size_ && "buffer subscript index out of range");
   126→
   127→		auto head = root_.next;
   128→		auto buffer = buffer_from_node(head);
   129→		const auto offset_index = index + buffer->read_offset;
   130→		const auto node_index = offset_index / block_sz;
   131→
   132→		for(size_type i = 0; i < node_index; ++i) {
   133→			head = head->next;
   134→		}
   135→
   136→		buffer = buffer_from_node(head);
   137→		return (*buffer)[offset_index % block_sz];
   138→	}
   139→
   140→	size_type abs_seek_offset(size_type offset) {
   141→		if(offset < size_) {
   142→			return size_ - offset;
   143→		} else if(offset > size_) {
   144→			return offset - size_;
   145→		} else {
   146→			return 0;
   147→		}
   148→	}
   149→
   150→	[[nodiscard]] storage_type* allocate() {
   151→		return allocator_.allocate();
   152→	}
   153→
   154→	void deallocate(storage_type* buffer) {
   155→		allocator_.deallocate(buffer);
   156→	}
   157→
   158→public:
   159→	dynamic_buffer()
   160→		: root_{ .next = &root_, .prev = &root_ },
   161→		  size_(0) {}
   162→
   163→	~dynamic_buffer() {
   164→		clear();
   165→	}
   166→
   167→	dynamic_buffer& operator=(dynamic_buffer&& rhs) noexcept {
   168→		move(rhs);
   169→		return *this;
   170→	}
   171→
   172→	dynamic_buffer(dynamic_buffer&& rhs) noexcept {
   173→		move(rhs);
   174→	}
   175→
   176→	dynamic_buffer(const dynamic_buffer& rhs) {
   177→		copy(rhs);
   178→	}
   179→
   180→	dynamic_buffer& operator=(const dynamic_buffer& rhs) {
   181→		clear();
   182→		copy(rhs);
   183→		return *this;
   184→	}
   185→
   186→	/**
   187→	 * @brief Reads a number of bytes to the provided buffer.
   188→	 * 
   189→	 * @note The destination buffer must not overlap with any of the underlying
   190→	 * buffers being used by the dynamic buffer.
   191→	 * 
   192→	 * @param[out] destination The buffer to copy the data to.
   193→	 */
   194→	template<typename T>
   195→	void read(T* destination) {
   196→		read(destination, sizeof(T));
   197→	}
   198→
   199→	/**
   200→	 * @brief Reads a number of bytes to the provided buffer.
   201→	 * 
   202→	 * @note The destination buffer must not overlap with any of the underlying
   203→	 * buffers being used by the dynamic buffer.
   204→	 * 
   205→	 * @param[out] destination The buffer to copy the data to.
   206→	 * @param length The number of bytes to read into the buffer.
   207→	 */
   208→	void read(void* destination, size_type length) override {
   209→		assert(length <= size_ && "Chained buffer read too large!");
   210→		size_type remaining = length;
   211→
   212→		while(true) {
   213→			auto buffer = buffer_from_node(root_.next);
   214→			remaining -= buffer->read(
   215→				static_cast<value_type*>(destination) + length - remaining, remaining,
   216→				                         root_.next == root_.prev
   217→			);
   218→
   219→			if(remaining) [[unlikely]] {
   220→				unlink_node(root_.next);
   221→				deallocate(buffer);
   222→			} else {
   223→				break;
   224→			}
   225→		}
   226→
   227→		size_ -= length;
   228→	}
   229→
   230→	/**
   231→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   232→	 * the container's read cursor.
   233→	 * 
   234→	 * @note The source buffer must not overlap with any of the underlying
   235→	 * buffers being used by the dynamic buffer.
   236→	 * 
   237→	 * @param[out] destination The buffer to copy the data to.
   238→	 */
   239→	template<typename T>
   240→	void copy(T* destination) const {
   241→		copy(destination, sizeof(T));
   242→	}
   243→
   244→	/**
   245→	 * @brief Copies a number of bytes to the provided buffer but without advancing
   246→	 * the container's read cursor.
   247→	 * 
   248→	 * @note The destination buffer must not overlap with any of the underlying
   249→	 * buffers being used by the dynamic buffer.
   250→	 * 
   251→	 * @param[out] destination The buffer to copy the data to.
   252→	 * @param length The number of bytes to copy.
   253→	 */
   254→	void copy(void* destination, const size_type length) const override {
   255→		assert(length <= size_ && "Chained buffer copy too large!");
   256→		size_type remaining = length;
   257→		auto head = root_.next;
   258→
   259→		while(true) {
   260→			const auto buffer = buffer_from_node(head);
   261→			remaining -= buffer->copy(
   262→				static_cast<value_type*>(destination) + length - remaining, remaining
   263→			);
   264→
   265→			if(remaining) [[unlikely]] {
   266→				head = head->next;
   267→			} else {
   268→				break;
   269→			}
   270→		}
   271→	}
   272→
   273→#ifdef HEXI_BUFFER_DEBUG
   274→	/**
   275→	 * @brief Retrives underlying buffers owned by the dynamic buffer.
   276→	 *
   277→	 * @param length Limit returned buffers to those holding up to the requested amount
   278→	 * of data.
   279→	 * @param offset The offset to start at.
   280→	 * 
   281→	 * @return Container of pointers to the underlying buffers holding the range of data
   282→	 * requested by length and offset.
   283→	 */
   284→	std::vector<storage_type*> fetch_buffers(const size_type length, const size_type offset = 0) {
   285→		size_type total = length + offset;
   286→		assert(total <= size_ && "Chained buffer fetch too large!");
   287→		std::vector<storage_type*> buffers;
   288→		auto head = root_.next;
   289→
   290→		while(total) {
   291→			auto buffer = buffer_from_node(head);
   292→			size_type read_size = block_sz - buffer->read_offset;
   293→			
   294→			// guard against overflow - buffer may have more content than requested
   295→			if(read_size > total) {
   296→				read_size = total;
   297→			}
   298→
   299→			buffers.emplace_back(buffer);
   300→			total -= read_size;
   301→			head = head->next;
   302→		}
   303→
   304→		if(offset) {
   305→			offset_buffers(buffers, offset);
   306→		}
   307→
   308→		return buffers;
   309→	}
   310→#endif
   311→
   312→	/**
   313→	 * @brief Skip the requested number of bytes.
   314→	 *
   315→	 * Skips over a number of bytes from the container. This should be used
   316→	 * if the container holds data that you don't care about but don't want
   317→	 * to have to read it to another buffer to access data beyond it.
   318→	 * 
   319→	 * @param length The number of bytes to skip.
   320→	 */
   321→	void skip(const size_type length) override {
   322→		assert(length <= size_ && "Chained buffer skip too large!");
   323→		size_type remaining = length;
   324→
   325→		while(true) {
   326→			auto buffer = buffer_from_node(root_.next);
   327→			remaining -= buffer->skip(remaining, root_.next == root_.prev);
   328→
   329→			if(remaining) [[unlikely]] {
   330→				unlink_node(root_.next);
   331→				deallocate(buffer);
   332→			} else {
   333→				break;
   334→			}
   335→		}
   336→
   337→		size_ -= length;
   338→	}
   339→
   340→	/**
   341→	 * @brief Write data to the container.
   342→	 * 
   343→	 * @note The source buffer must not overlap with any of the underlying buffers
   344→	 * being used by the dynamic buffer.
   345→	 * 
   346→	 * @param source Pointer to the data to be written.
   347→	 */
   348→	void write(const auto& source) {
   349→		write(&source, sizeof(source));
   350→	}
   351→
   352→	/**
   353→	 * @brief Write provided data to the container.
   354→	 * 
   355→	 * @note The source buffer must not overlap with any of the underlying buffers
   356→	 * being used by the dynamic buffer.
   357→	 * 
   358→	 * @param source Pointer to the data to be written.
   359→	 * @param length Number of bytes to write from the source.
   360→	 */
   361→	void write(const void* source, const size_type length) override {
   362→		size_type remaining = length;
   363→		intrusive_node* tail = root_.prev;
   364→
   365→		do {
   366→			storage_type* buffer;
   367→
   368→			if(tail != &root_) [[likely]] {
   369→				buffer = buffer_from_node(tail);
   370→			} else {
   371→				buffer = allocate();
   372→				link_tail_node(&buffer->node);
   373→				tail = root_.prev;
   374→			}
   375→
   376→			remaining -= buffer->write(
   377→				static_cast<const value_type*>(source) + length - remaining, remaining
   378→			);
   379→
   380→			tail = tail->next;
   381→		} while(remaining);
   382→
   383→		size_ += length;
   384→	}
   385→
   386→	/**
   387→	 * @brief Reserves a number of bytes within the container for future use.
   388→	 * 
   389→	 * @param length The number of bytes that the container should reserve.
   390→	 */
   391→	void reserve(const size_type length) override {
   392→		size_type remaining = length;
   393→		intrusive_node* tail = root_.prev;
   394→
   395→		do {
   396→			storage_type* buffer;
   397→
   398→			if(tail == &root_) [[unlikely]] {
   399→				buffer = allocate();
   400→				link_tail_node(&buffer->node);
   401→				tail = root_.prev;
   402→			} else {
   403→				buffer = buffer_from_node(tail);
   404→			}
   405→
   406→			remaining -= buffer->advance_write(remaining);
   407→			tail = tail->next;
   408→		} while(remaining);
   409→
   410→		size_ += length;
   411→	}
   412→
   413→	/**
   414→	 * @brief Returns the size of the container.
   415→	 * 
   416→	 * @return The number of bytes of data available to read within the container.
   417→	 */
   418→	size_type size() const override {
   419→		return size_;
   420→	}
   421→
   422→	/**
   423→	 * @brief Retrieves the last buffer in the container's list.
   424→	 * 
   425→	 * @return A reference to the value at the specified index.
   426→	 * @note The container retains ownership over the buffer, so it must not
   427→	 * be deallocated by the caller.
   428→	 */
   429→	storage_type* back() const {
   430→		if(root_.prev == &root_) {
   431→			return nullptr;
   432→		}
   433→
   434→		return buffer_from_node(root_.prev);
   435→	}
   436→
   437→	/**
   438→	 * @brief Retrieves the buffer's block sized.
   439→	 * 
   440→	 * @param index The index within the buffer.
   441→	 * @return A reference to the value at the specified index.
   442→	 */
   443→	storage_type* front() const {
   444→		if(root_.next == &root_) {
   445→			return nullptr;
   446→		}
   447→
   448→		return buffer_from_node(root_.next);
   449→	}
   450→
   451→	/**
   452→	 * @brief Removes the first buffer from the container.
   453→	 * 
   454→	 * @return A pointer to the popped buffer.
   455→	 * 
   456→	 * @note Removing the buffer from the container also transfers ownership.
   457→	 * Therefore, the caller assumes responsibility for deallocating the buffer
   458→	 * when it is no longer required. Alternatively, it can be pushed back into
   459→	 * the container to transfer ownership back.
   460→	 */
   461→	auto pop_front() {
   462→		auto buffer = buffer_from_node(root_.next);
   463→		size_ -= buffer->size();
   464→		unlink_node(root_.next);
   465→		return unique_storage(buffer, [&](auto ptr) {
   466→			deallocate(ptr);
   467→		});
   468→	}
   469→
   470→	/**
   471→	 * @brief Attaches additional storage to the container.
   472→	 * 
   473→	 * @param buffer The block to add to the container.
   474→	 * 
   475→	 * @note Once pushed, the container is assumed to have ownership over the buffer.
   476→	 * The buffer storage must have been allocated by the same allocator as the container.
   477→	 */
   478→	void push_back(storage_type* buffer) {
   479→		link_tail_node(&buffer->node);
   480→		size_ += buffer->write_offset;
   481→	}
   482→
   483→	/**
   484→	 * @brief Advances the write cursor.
   485→	 * 
   486→	 * @param size The number of bytes by which the write cursor to advance the cursor.
   487→	 */
   488→	void advance_write(const size_type size) {
   489→		auto buffer = buffer_from_node(root_.prev);
   490→		const auto actual = buffer->advance_write(size);
   491→		assert(size <= block_sz && actual <= size &&
   492→		       "Attempted to advance write cursor out of bounds!");
   493→		size_ += size;
   494→	}
   495→
   496→	/**
   497→	 * @brief Determine whether the adaptor supports write seeking.
   498→	 * 
   499→	 * This is determined at compile-time and does not need to checked at
   500→	 * run-time.
   501→	 * 
   502→	 * @return True if write seeking is supported, otherwise false.
   503→	 */
   504→	bool can_write_seek() const override {
   505→		return std::is_same_v<seeking, supported>;
   506→	}
   507→
   508→	/**
   509→	 * @brief Performs write seeking within the container.
   510→	 * 
   511→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   512→	 * @param offset The offset relative to the seek direction or the absolute value
   513→	 * when using absolute seeking.
   514→	 */
   515→	void write_seek(const buffer_seek direction, size_type offset) override {
   516→		// nothing to do in this case
   517→		if(direction == buffer_seek::sk_absolute && offset == size_) {
   518→			return;
   519→		}
   520→
   521→		auto tail = root_.prev;
   522→
   523→		switch(direction) {
   524→			case buffer_seek::sk_backward:
   525→				size_ -= offset;
   526→				break;
   527→			case buffer_seek::sk_forward:
   528→				size_ += offset;
   529→				break;
   530→			case buffer_seek::sk_absolute:
   531→				size_ = offset;
   532→				offset = abs_seek_offset(offset);
   533→				break;
   534→		}
   535→
   536→		const bool rewind
   537→			= (direction == buffer_seek::sk_backward
   538→			   || (direction == buffer_seek::sk_absolute && offset < size_));
   539→
   540→		while(offset) {
   541→			auto buffer = buffer_from_node(tail);
   542→			const auto max_seek = rewind? buffer->size() : buffer->free();
   543→
   544→			if(max_seek >= offset) {
   545→				buffer->write_seek(direction, offset);
   546→				offset = 0;
   547→			} else {
   548→				buffer->write_seek(direction, max_seek);
   549→				offset -= max_seek;
   550→				tail = rewind? tail->prev : tail->next;
   551→			}
   552→		}
   553→
   554→		root_.prev = tail;
   555→	}
   556→
   557→	/**
   558→	 * @brief Clears the container.
   559→	 */
   560→	void clear() {
   561→		intrusive_node* head = root_.next;
   562→
   563→		while(head != &root_) {
   564→			auto next = head->next;
   565→			deallocate(buffer_from_node(head));
   566→			head = next;
   567→		}
   568→
   569→		root_.next = &root_;
   570→		root_.prev = &root_;
   571→		size_ = 0;
   572→	}
   573→
   574→	/**
   575→	 * @brief Whether the container is empty.
   576→	 * 
   577→	 * @return Returns true if the container is empty (has no data to be read).
   578→	 */
   579→	[[nodiscard]]
   580→	bool empty() const override {
   581→		return !size_;
   582→	}
   583→
   584→	/**
   585→	 * @brief Retrieves the container's block size.
   586→	 * 
   587→	 * @return The block size.
   588→	 */
   589→	constexpr static size_type block_size() {
   590→		return block_sz;
   591→	}
   592→
   593→	/**
   594→	 * @brief Retrieves a reference to the specified index within the container.
   595→	 * 
   596→	 * @param index The index within the container.
   597→	 * 
   598→	 * @return A reference to the value at the specified index.
   599→	 */
   600→	value_type& operator[](const size_type index) override {
   601→		return byte_at_index(index);
   602→	}
   603→
   604→	/**
   605→	 * @brief Retrieves a reference to the specified index within the container.
   606→	 * 
   607→	 * @param index The index within the container.
   608→	 * 
   609→	 * @return A reference to the value at the specified index.
   610→	 */
   611→	const value_type& operator[](const size_type index) const override {
   612→		return byte_at_index(index);
   613→	}
   614→
   615→	/**
   616→	 * @brief Retrieves the number of allocated blocks currently being used by the container.
   617→	 * 
   618→	 * @return The number of allocated blocks.
   619→	 */
   620→	size_type block_count() const {
   621→		auto node = &root_;
   622→		size_type count = 0;
   623→
   624→		// not calculating based on block size & size as it
   625→		// wouldn't play nice with seeking or manual push/pop
   626→		while(node->next != root_.prev->next) {
   627→			++count;
   628→			node = node->next;
   629→		}
   630→
   631→		return count;
   632→	}
   633→
   634→	/**
   635→	 * @brief Attempts to locate the provided value within the container.
   636→	 * 
   637→	 * @param value The value to locate.
   638→	 * 
   639→	 * @return The position of value or npos if not found.
   640→	 */
   641→	size_type find_first_of(value_type value) const override {
   642→		size_type index = 0;
   643→		auto head = root_.next;
   644→
   645→		while(head != &root_) {
   646→			const auto buffer = buffer_from_node(head);
   647→			const auto data = buffer->read_data();
   648→			
   649→			for(const auto& byte : data) {
   650→				if(byte == value) {
   651→					return index;
   652→				}
   653→
   654→				++index;
   655→			}
   656→
   657→			head = head->next;
   658→		}
   659→
   660→		return npos;
   661→	}
   662→
   663→	/**
   664→	 * @brief Retrieves the container's allocator.
   665→	 * 
   666→	 * @return The memory allocator.
   667→	 */
   668→	auto& get_allocator() {
   669→		return allocator_;
