// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // Create a block_allocator with a pre-allocated pool of element_count blocks
    // The constructor internally calls initialise_free_list() which builds a
    // linked list by calling push() for each block in the storage slab
    hexi::block_allocator<std::uint64_t, element_count> allocator;

    std::cout << "=== Block Allocator Free List Demonstration ===" << std::endl;
    std::cout << "Pre-allocated capacity: " << element_count << " blocks\n" << std::endl;

    // Internal state after construction:
    // - head_ points to the last block pushed (LIFO structure)
    // - All blocks are linked: block[N-1] -> block[N-2] -> ... -> block[0] -> nullptr

    std::cout << "1. Initial state (all blocks in free list):" << std::endl;
    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Active allocations: " << allocator.active_count << std::endl;
    std::cout << "   Storage pool active: " << allocator.storage_active_count << std::endl;
    std::cout << "   Heap allocations active: " << allocator.new_active_count << std::endl;
    #endif
    std::cout << std::endl;

    // Demonstrate pop() behavior through allocate()
    // Each allocate() internally calls pop() which:
    // 1. Returns nullptr if head_ is nullptr
    // 2. Otherwise, saves current head_, updates head_ = head_->next, returns saved block
    std::cout << "2. Allocating 5 blocks (each allocate() internally calls pop()):" << std::endl;
    std::vector<std::uint64_t*> allocated_blocks;

    for (size_t i = 0; i < 5; ++i) {
        auto* block = allocator.allocate(i * 100);  // Initialize with value
        allocated_blocks.push_back(block);
        std::cout << "   Allocated block " << i << " with value: " << *block << std::endl;
