Now I have a complete understanding of how the `block_allocator` works. Let me create a comprehensive demonstration function that shows the free list management behavior:

```cpp
#include <hexi/allocators/block_allocator.h>
#include <cstdint>
#include <iostream>
#include <vector>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // Create a block_allocator with a pre-allocated pool of element_count blocks
    // The constructor internally calls initialise_free_list() which builds a
    // linked list by calling push() for each block in the storage slab
    hexi::block_allocator<std::uint64_t, element_count> allocator;

    std::cout << "=== Block Allocator Free List Demonstration ===" << std::endl;
    std::cout << "Pre-allocated capacity: " << element_count << " blocks\n" << std::endl;

    // Internal state after construction:
    // - head_ points to the last block pushed (LIFO structure)
    // - All blocks are linked: block[N-1] -> block[N-2] -> ... -> block[0] -> nullptr

    std::cout << "1. Initial state (all blocks in free list):" << std::endl;
    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Active allocations: " << allocator.active_count << std::endl;
    std::cout << "   Storage pool active: " << allocator.storage_active_count << std::endl;
    std::cout << "   Heap allocations active: " << allocator.new_active_count << std::endl;
    #endif
    std::cout << std::endl;

    // Demonstrate pop() behavior through allocate()
    // Each allocate() internally calls pop() which:
    // 1. Returns nullptr if head_ is nullptr
    // 2. Otherwise, saves current head_, updates head_ = head_->next, returns saved block
    std::cout << "2. Allocating 5 blocks (each allocate() internally calls pop()):" << std::endl;
    std::vector<std::uint64_t*> allocated_blocks;

    for (size_t i = 0; i < 5; ++i) {
        auto* block = allocator.allocate(i * 100);  // Initialize with value
        allocated_blocks.push_back(block);
        std::cout << "   Allocated block " << i << " with value: " << *block << std::endl;
    }

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Active allocations: " << allocator.active_count << std::endl;
    std::cout << "   Storage pool active: " << allocator.storage_active_count << std::endl;
    std::cout << "   Total allocations made: " << allocator.total_allocs << std::endl;
    #endif
    std::cout << std::endl;

    // After 5 allocations via pop():
    // - head_ has moved forward 5 times in the free list
    // - 5 blocks are now in use, (element_count - 5) blocks remain in free list

    // Demonstrate push() behavior through deallocate()
    // Each deallocate() internally calls push() which:
    // 1. Sets block->next = head_
    // 2. Updates head_ = block
    // This makes it LIFO - last deallocated block becomes the new head
    std::cout << "3. Deallocating 3 blocks (each deallocate() internally calls push()):" << std::endl;

    for (size_t i = 0; i < 3; ++i) {
        std::cout << "   Deallocating block " << i << " (value: " << *allocated_blocks[i] << ")" << std::endl;
        allocator.deallocate(allocated_blocks[i]);
    }
    allocated_blocks.erase(allocated_blocks.begin(), allocated_blocks.begin() + 3);

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Active allocations: " << allocator.active_count << std::endl;
    std::cout << "   Storage pool active: " << allocator.storage_active_count << std::endl;
    std::cout << "   Total deallocations made: " << allocator.total_deallocs << std::endl;
    #endif
    std::cout << std::endl;

    // After 3 deallocations via push():
    // - The 3 deallocated blocks are now at the head of the free list
    // - They were added in reverse order (LIFO): block[2] -> block[1] -> block[0] -> rest of list

    // Demonstrate LIFO behavior
    std::cout << "4. Allocating 3 more blocks (shows LIFO order from free list):" << std::endl;
    std::cout << "   (These will reuse the just-deallocated blocks in reverse order)" << std::endl;

    for (size_t i = 0; i < 3; ++i) {
        auto* block = allocator.allocate(999);
        allocated_blocks.push_back(block);
        std::cout << "   Re-allocated block " << i << " with new value: " << *block << std::endl;
    }

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Active allocations: " << allocator.active_count << std::endl;
    std::cout << "   Storage pool active: " << allocator.storage_active_count << std::endl;
    #endif
    std::cout << std::endl;

    // Demonstrate fallback to heap when free list is exhausted
    std::cout << "5. Allocating beyond capacity (triggers fallback to heap):" << std::endl;
    std::cout << "   Current allocations: 5, Capacity: " << element_count << std::endl;

    // Allocate more blocks to exhaust the free list
    for (size_t i = 5; i < element_count + 2; ++i) {
        auto* block = allocator.allocate(i * 1000);
        allocated_blocks.push_back(block);

        if (i >= element_count) {
            std::cout << "   Block " << i << " allocated from HEAP (free list exhausted)" << std::endl;
        }
    }

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Total active allocations: " << allocator.active_count << std::endl;
    std::cout << "   From storage pool: " << allocator.storage_active_count << std::endl;
    std::cout << "   From heap (new): " << allocator.new_active_count << std::endl;
    #endif
    std::cout << std::endl;

    // When pop() returns nullptr (free list empty):
    // - allocator falls back to using 'new' to allocate from heap
    // - These heap allocations are tracked separately (using_new flag set to true)

    std::cout << "6. Cleanup - deallocating all blocks:" << std::endl;
    for (auto* block : allocated_blocks) {
        allocator.deallocate(block);
        // Heap blocks (using_new == true) are deleted
        // Storage pool blocks are pushed back to free list
    }

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "   Final active allocations: " << allocator.active_count << std::endl;
    std::cout << "   Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "   Total deallocations: " << allocator.total_deallocs << std::endl;
    #endif

    std::cout << "\n=== Summary of Free List Operations ===" << std::endl;
    std::cout << "push(block): Adds block to head of free list (LIFO)" << std::endl;
    std::cout << "  - Sets block->next = current head" << std::endl;
    std::cout << "  - Updates head = block" << std::endl;
    std::cout << "\npop(): Removes and returns head block from free list" << std::endl;
    std::cout << "  - Saves current head" << std::endl;
    std::cout << "  - Updates head = head->next" << std::endl;
    std::cout << "  - Returns saved block (or nullptr if list was empty)" << std::endl;
}
```

This complete implementation demonstrates:

1. **Initialization**: The free list is built during construction via repeated `push()` calls
2. **Allocation via `pop()`**: Shows how blocks are removed from the head of the free list
3. **Deallocation via `push()`**: Shows how blocks are returned to the head (LIFO behavior)
4. **LIFO ordering**: Demonstrates that the last deallocated block is the first to be reallocated
5. **Heap fallback**: Shows what happens when the free list is exhausted (`pop()` returns `nullptr`)
6. **Debug statistics**: Uses the debug counters to track internal state changes

The function can be called with different template parameters to test various pool sizes, e.g., `demonstrate_block_allocator_behavior<5>()` or `demonstrate_block_allocator_behavior<20>()`.

