std::vector<uint8_t> preview_data_without_consuming(const hexi::detail::intrusive_storage<block_size>& storage, size_t bytes_to_preview) {
    // Create a destination buffer for the preview
    std::vector<uint8_t> preview_buffer(bytes_to_preview);

    // Use the copy() method which reads data without advancing the read pointer
    size_t bytes_copied = storage.copy(preview_buffer.data(), bytes_to_preview);

    // Resize the vector to match the actual number of bytes copied
    // (in case fewer bytes were available than requested)
    preview_buffer.resize(bytes_copied);

    return preview_buffer;
}

