std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    // Create a file_buffer for the specified file
    hexi::file_buffer file(file_path);

    // Check if file opened successfully
    if (!file) {
        return {};
    }

    // Limit bytes_to_read to available data
    size_t available = file.size();
    size_t to_read = (bytes_to_read < available) ? bytes_to_read : available;

    // Create destination buffer
    std::vector<uint8_t> buffer(to_read);

    // Read data from file
    file.read(buffer.data(), to_read);

    // Check if read was successful
    if (!file) {
        return {};
    }

    return buffer;
}

