    // Create a vector to hold the header data
    std::vector<uint8_t> header(bytes_to_read);

    // Use copy() to read data without advancing the read pointer
    buffer.copy(header.data(), bytes_to_read);

    // Check if the copy operation succeeded
    if (!buffer) {
        return {}; // Return empty vector on error
    }

    return header;
}
