#include <hexi/static_buffer.h>
#include <vector>
#include <cstdint>

template<size_t buffer_size = 1024>
void write_data_to_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer, const std::vector<uint8_t>& data) {
    // Convert uint8_t data to std::byte and write to the buffer
    buffer.write(reinterpret_cast<const std::byte*>(data.data()), data.size());
}

template<size_t buffer_size = 1024>
std::vector<uint8_t> read_data_from_buffer(hexi::static_buffer<std::byte, buffer_size>& buffer, size_t bytes_to_read) {
    // Create a vector to hold the read data
    std::vector<uint8_t> result(bytes_to_read);

    // Read data from the buffer into the vector
    buffer.read(reinterpret_cast<std::byte*>(result.data()), bytes_to_read);

    return result;
}
```

## Explanation:

### `write_data_to_buffer`:
- Takes a `static_buffer` of `std::byte` and a `std::vector<uint8_t>` containing the data to write
- Uses `reinterpret_cast` to convert the `uint8_t*` pointer to `const std::byte*` (both are 1-byte types, so this is safe)
- Calls the buffer's `write()` method with the data pointer and size
- The buffer will throw `hexi::buffer_overflow` if there's insufficient space

### `read_data_from_buffer`:
- Takes a `static_buffer` of `std::byte` and the number of bytes to read
- Creates a `std::vector<uint8_t>` with the appropriate size to hold the result
- Uses `reinterpret_cast` to convert the `uint8_t*` pointer to `std::byte*` for reading
- Calls the buffer's `read()` method which copies data and advances the read cursor
- Returns the vector containing the read data
- The buffer will throw `hexi::buffer_underrun` if there are insufficient bytes available to read

Both functions leverage the `static_buffer`'s built-in error handling and memory management, making them safe and straightforward to use.

