    43→class binary_stream_reader : virtual public stream_base {
    44→	buffer_read& buffer_;
    45→	std::size_t total_read_;
    46→	const std::size_t read_limit_;
    47→
    48→	inline void enforce_read_bounds(const std::size_t read_size) {
    49→		if(read_size > buffer_.size()) [[unlikely]] {
    50→			set_state(stream_state::buff_limit_err);
    51→
    52→			if(allow_throw()) {
    53→				HEXI_THROW(buffer_underrun(read_size, total_read_, buffer_.size()));
    54→			}
    55→
    56→			return;
    57→		}
    58→
    59→		if(read_limit_) {
    60→			const auto max_read_remaining = read_limit_ - total_read_;
    61→
    62→			if(read_size > max_read_remaining) [[unlikely]] {
    63→				set_state(stream_state::read_limit_err);
    64→
    65→				if(allow_throw()) {
    66→					HEXI_THROW(stream_read_limit(read_size, total_read_, read_limit_));
    67→				}
    68→
    69→				return;
    70→			}
    71→		}
    72→
    73→		total_read_ += read_size;
    74→	}
