   522→	 * @param[out] adaptor std::string to hold the result.
   523→	 * 
   524→	 * @return Reference to the current stream.
   525→	 */
   526→	binary_stream& operator>>(prefixed<std::string> adaptor) {
   527→		std::uint32_t size = 0;
   528→		*this >> endian::le(size);
   529→
   530→		if(state_ != stream_state::ok) {
   531→			return *this;
   532→		}
   533→
   534→		STREAM_READ_BOUNDS_ENFORCE(size, *this);
   535→
   536→		adaptor->resize_and_overwrite(size, [&](char* strbuf, std::size_t size) {
   537→			buffer_.read(strbuf, size);
   538→			return size;
   539→		});
   540→
   541→		return *this;
   542→	}
