std::vector<uint8_t> serialize_with_padding(const PaddedData& packet) {
    // Create a vector to hold the serialized data
    std::vector<uint8_t> buffer;

    // Wrap the buffer with an adaptor
    hexi::buffer_adaptor adaptor(buffer);

    // Create a binary stream with little-endian byte order (common for network protocols)
    hexi::binary_stream stream(adaptor);

    // Write header (uint16_t)
    stream << packet.header;

    // Write data string with length prefix (default behavior for std::string)
    stream << packet.data;

    // Write 16 bytes of padding filled with 0x00
    stream.fill<16>(0x00);

    // Write footer (uint32_t)
    stream << packet.footer;

    return buffer;
}
