    std::vector<uint8_t> buffer;

    // Create a write adaptor to write data to the buffer
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> writer(buffer, hexi::pmc::init_empty);

    // Check available space before writing (optional, but good practice)
    // Note: For resizable containers like std::vector, this will auto-resize on write

    // Write the input data to the buffer
    writer.write(input_data.data(), input_data.size());

    // Create a read adaptor to read data from the buffer
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer);

    // Check the readable size
    std::size_t readable_size = reader.size();

    // Create output vector to store the read data
    std::vector<uint8_t> output_data(readable_size);

    // Read data back from the buffer
    reader.read(output_data.data(), readable_size);

    return output_data;
}

std::vector<uint8_t> peek_data_without_advancing(const std::vector<uint8_t>& buffer_data, std::size_t peek_size) {
    // Create a mutable copy of the buffer since adaptors require non-const reference
    std::vector<uint8_t> buffer(buffer_data);

    // Create a read adaptor for the buffer
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer);

    // Get pointer to current read position
    auto read_position = reader.read_ptr();

    // Create output vector for peeked data
