    // After copy(), the read pointer should still be at the same position

    // Now use read() to actually consume the data (advances the cursor)
    std::vector<uint8_t> consumed_data(peek_size);
    reader.read(consumed_data.data(), peek_size);

    // Return the peeked data (which should be identical to consumed_data)
    return peeked_data;
}
