    70→	void write(const auto& source) {
    71→		buffer_write_adaptor<buf_type>::write(source);
    72→	};
    73→
    74→	/**
    75→	 * @brief Write provided data to the container.
    76→	 * 
    77→	 * @param source Pointer to the data to be written.
    78→	 * @param length Number of bytes to write from the source.
    79→	 */
    80→	void write(const void* source, std::size_t length) override {
    81→		buffer_write_adaptor<buf_type>::write(source, length);
    82→	};
    83→
