   200→	/**
   201→	 * @brief Clears the underlying buffer, resetting both the read
   202→	 * and write cursors.
   203→	 */
   204→	void clear() {
   205→		buffer_read_adaptor<buf_type>::clear();
   206→		buffer_write_adaptor<buf_type>::clear();
   207→	}
   208→};
