#include <hexi/pmc/buffer_read_adaptor.h>
#include <hexi/pmc/buffer_write_adaptor.h>
#include <vector>
#include <cstdint>

std::size_t write_multiple_chunks(const std::vector<std::vector<uint8_t>>& chunks) {
    // Create a vector buffer to hold the data
    std::vector<uint8_t> buffer;

    // Create a write adaptor with empty initialization
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> writer(buffer, hexi::init_empty);

    // Write each chunk, checking available space before each write
    for (const auto& chunk : chunks) {
        // Check available space using free()
        std::size_t available = writer.free();

        // Write the chunk data
        writer.write(chunk.data(), chunk.size());
    }

    // Return the total size written (write offset)
    return writer.write_offset();
}

std::vector<uint8_t> read_partial_data(const std::vector<uint8_t>& buffer, std::size_t chunk_size) {
    // Create a mutable copy of the buffer since the adaptor requires a non-const reference
    std::vector<uint8_t> buffer_copy = buffer;

    // Create a read adaptor
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(buffer_copy);

    // Result vector to store all read data
    std::vector<uint8_t> result;

    // Read until buffer is empty
    while (!reader.empty()) {
        // Check remaining data size
        std::size_t remaining = reader.size();

        // Determine how much to read in this iteration
        std::size_t to_read = std::min(chunk_size, remaining);

        // Create temporary buffer for this chunk
        std::vector<uint8_t> temp(to_read);

        // Read the chunk
        reader.read(temp.data(), to_read);

        // Append to result
        result.insert(result.end(), temp.begin(), temp.end());
    }

    // Return all read data
    return result;
}
```

