};

std::vector<uint8_t> serialize_protocol_packet(const ProtocolPacket& packet) {
    // Create a buffer and stream for writing
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer, hexi::init_empty);
    hexi::binary_stream stream(adaptor);

    // Convert message_id to big-endian and write
    auto message_id_be = hexi::endian::native_to_big(packet.message_id);
    stream.put(&message_id_be, 1);

    // Write the count of data_values (converted to big-endian)
    auto count_be = hexi::endian::native_to_big(static_cast<uint32_t>(packet.data_values.size()));
    stream.put(&count_be, 1);

    // Convert each element in data_values to big-endian and write
    for (const auto& value : packet.data_values) {
        auto value_be = hexi::endian::native_to_big(value);
        stream.put(&value_be, 1);
    }

    // Convert checksum to big-endian and write
    auto checksum_be = hexi::endian::native_to_big(packet.checksum);
    stream.put(&checksum_be, 1);

    return buffer;
}

