#include <hexi/hexi.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>
#include <string>

struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly (no endianness conversion needed for this field)
        adaptor & sensor_id;

        // Write the number of temperature values as a prefix
        adaptor & static_cast<uint32_t>(temperatures.size());

        // Convert each temperature from native to little-endian before writing
        for (const auto& temp : temperatures) {
            auto converted = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.forward(&converted, sizeof(converted));
        }

        // Convert pressure from native to little-endian before writing
        auto converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.forward(&converted_pressure, sizeof(converted_pressure));
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor & sensor_id;

        // Read the number of temperature values
        uint32_t temp_count = 0;
        adaptor & temp_count;

        // Read each temperature value and convert from little-endian to native in-place
        temperatures.resize(temp_count);
        for (auto& temp : temperatures) {
            adaptor.forward(&temp, sizeof(temp));
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native in-place
        adaptor.forward(&pressure, sizeof(pressure));
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    stream.serialise(data);

    return buffer;
}

MeasurementData deserialize_measurement_data(const std::span<const uint8_t> buffer) {
    // Create a mutable copy for the buffer_adaptor
    std::vector<uint8_t> buffer_copy(buffer.begin(), buffer.end());
    hexi::buffer_adaptor adaptor(buffer_copy);
    hexi::binary_stream stream(adaptor);

    MeasurementData data;
    stream.deserialise(data);

    return data;
}

struct SensorInfo {
    uint32_t sensor_id;
    std::string_view sensor_name;
};

SensorInfo extract_sensor_info(const std::span<const uint8_t> buffer) {
    // Create a mutable copy for the buffer_adaptor
    std::vector<uint8_t> buffer_copy(buffer.begin(), buffer.end());
    hexi::buffer_adaptor adaptor(buffer_copy);
    hexi::binary_stream stream(adaptor);

    SensorInfo info;

    // Extract null-terminated sensor name string (if present)
    info.sensor_name = stream.view();

    // Check if there's enough data to read the sensor_id
    constexpr auto sensor_id_size = sizeof(uint32_t);
    if (stream.size() < sensor_id_size) {
        // Not enough data, return default values
        info.sensor_id = 0;
        return info;
    }

    // Read the sensor_id directly
    stream >> info.sensor_id;

    // Skip the remaining data
    if (stream.size() > 0) {
        stream.skip(stream.size());
    }

    return info;
}

